import java.util.*;

public class Main {
    public static void main(String[] args) {

        // Try using LinkedList as a stack — push and pop elements!
        Deque<String> stack = new LinkedList<>();

        stack.push("First");
        stack.push("Second");
        stack.push("Third");

        System.out.println("Stack: " + stack);

        while (!stack.isEmpty()) {
            System.out.println("Popped: " + stack.pop());
        }
    }
}

